/**
 * A creative regenerated by AI in another size, shown for the person to look at before it is used (both workflows: the
 * first-time master and Create Offer Creative): what it was made from beside it, what was checked on this computer (its
 * exact size; every QR code scanning to its own link — kept, or put back from the original; the products and logos put
 * back with their own pixels; words of the original not read in it), what the request cost, and the confirmation that
 * they looked at it. What happens next is the caller's (its actions, below).
 */
import { Check, Sparkles } from 'lucide-react';
import { REUSE_ASPECT_LABELS, RATIO_REQUEST_SIZES, type RegeneratedImage } from '@frameflow/shared';

export function RegeneratedResult({ beforeUrl, beforeLabel, resultUrl, result, approved, onApproved, children }: {
  beforeUrl?: string; beforeLabel: string; resultUrl: string; result: RegeneratedImage;
  approved: boolean; onApproved: (v: boolean) => void; children?: React.ReactNode;
}) {
  const label = REUSE_ASPECT_LABELS[result.ratio], c = result.checks, blocked = c.blocking.length > 0;
  const rows: [string, boolean, string][] = [
    ['Size', true, `${result.width} × ${result.height} px — exactly ${result.ratio}.${RATIO_REQUEST_SIZES[result.ratio] ? ' Made at 3:1 (the widest the image model makes), its plain top and bottom edges trimmed to the exact ratio.' : ''}`],
    ['QR codes', !c.qr.some(q => q.status === 'failed'), c.qr.length ? c.qr.map(q => (q.status === 'kept' ? 'Scans to the same link as your original.' : q.status === 'restored' ? 'Redrawn by the AI — your original QR code was put back; it scans to the same link.' : 'Does not scan to your original link.')).join(' ') : 'None in your original.'],
    ...(c.assets.length ? [['Products & logos', !c.assets.some(a => a.status === 'not-found'), c.assets.map(a => `${a.label}: ${a.status === 'restored' ? 'your own picture put back' : 'not found — check it'}`).join(' · ')] as [string, boolean, string]] : []),
    ['Text', !c.missingWords.length, c.missingWords.length ? `Not read in the regenerated creative — check these: ${c.missingWords.join(', ')}. You can also correct text in the review that follows.` : 'Every word read in your original was found again (read on this computer). You check every word again in the review that follows.'],
    ...(c.extraWords ? [['Nothing added', !c.extraWords.length, c.extraWords.length ? `Read in the regenerated creative but not in your original — check for invented copy: ${c.extraWords.join(', ')}. Regenerate it, or continue with your original, if the AI added text.` : 'No word was read in it that your original does not have (read on this computer).'] as [string, boolean, string]] : []),
  ];
  return <section className="rg-result" aria-label={`Regenerated in ${label}`}>
    <div className="rg-compare">
      {beforeUrl && <figure><img src={beforeUrl} alt={beforeLabel} /><figcaption>{beforeLabel}</figcaption></figure>}
      <figure className="is-result"><img src={resultUrl} alt={`Your creative regenerated by AI in ${label}`} /><figcaption><Sparkles size={13} aria-hidden="true" />Regenerated by AI · {label} · {result.model}</figcaption></figure>
    </div>
    <ul className="sr-checks" aria-label="Checked before you use it">{rows.map(([title, ok, text]) => <li key={title} className={ok ? 'is-ok' : 'is-warn'}>
      <span className="sr-check-mark" aria-hidden="true">{ok ? <Check size={12} /> : '!'}</span><span><strong>{title}</strong> {text}</span></li>)}</ul>
    {blocked && <div className="sr-error" role="alert"><p>This result can’t be used:</p><ul>{c.blocking.map(b => <li key={b}>{b}</li>)}</ul></div>}
    <p className="ot-muted ot-small">One request to {result.model}{result.costUsd !== undefined ? `, $${result.costUsd.toFixed(3)} (from the response’s usage)` : `, estimated at most $${result.estimateUsd.toFixed(2)}`}. Nothing is used until you confirm.</p>
    {!blocked && <label className="ot-check"><input type="checkbox" checked={approved} onChange={e => onApproved(e.target.checked)} />
      <span>I have looked at the regenerated creative: its text, prices, dates, products, logos and QR code are right.</span></label>}
    {children}
  </section>;
}
